// UNDEFINED BEHAVIOR - Strict aliasing violations:
int i = 42;
float* fp = (float*)&i;
float f = *fp;  // UB: accessing int storage through float*

// LEGAL - Same type
int i2 = *(int*)&i;  // OK: accessing int through int*

// LEGAL - cv-qualified version
const int* cip = &i;
int i3 = *cip;  // OK: accessing int through const int* (lvalue-to-rvalue)

// LEGAL - Signed/unsigned correspondence
unsigned int ui = 100;
int* ip = (int*)&ui;
int si = *ip;  // OK: signed/unsigned correspondence

// LEGAL - char/unsigned char (byte access)
char* cp = (char*)&i;
char byte0 = cp[0];  // OK: char* can alias anything

// LEGAL - Base class access
class Base {};
class Derived : public Base {};
Derived d;
Base* bp = &d;
Base& br = *bp;  // OK: accessing Derived through Base*

// LEGAL - Aggregate containing the type
struct S { int x; };
S s;
int* ip2 = &s.x;
int val = *ip2;  // OK: accessing int member through int*

