#include <iostream>
#include <cstring>
#include <cstdint>

// Example 1: Undefined Behavior - Type punning violation
void demonstrate_ub_violation() {
    std::cout << "--- UNDEFINED BEHAVIOR Example ---\n";

    int i = 0x12345678;
    // float* fp = (float*)&i;
    // float f = *fp;  // UB: accessing int through float*

    std::cout << "Commented out to avoid UB\n";
    std::cout << "Accessing int through float* is UNDEFINED BEHAVIOR\n\n";
}

// Example 2: LEGAL - char* byte access
void demonstrate_char_access() {
    std::cout << "--- LEGAL: Byte Access with char* ---\n";

    int32_t value = 0x12345678;
    unsigned char* bytes = (unsigned char*)&value;

    std::cout << "Value: 0x" << std::hex << value << std::dec << "\n";
    std::cout << "Bytes (little-endian): ";
    for (size_t i = 0; i < sizeof(value); ++i) {
        printf("%02X ", bytes[i]);
    }
    std::cout << "\n\n";
}

// Example 3: SAFE - memcpy for type punning
void demonstrate_memcpy() {
    std::cout << "--- SAFE: Type Punning with memcpy ---\n";

    float f = 3.14159f;
    uint32_t bits;

    // Safe way to inspect float representation
    std::memcpy(&bits, &f, sizeof(f));

    std::cout << "Float value: " << f << "\n";
    std::cout << "Bit pattern: 0x" << std::hex << bits << std::dec << "\n\n";
}

// Example 4: LEGAL - Signed/unsigned correspondence
void demonstrate_signed_unsigned() {
    std::cout << "--- LEGAL: Signed/Unsigned Correspondence ---\n";

    unsigned int ui = 0xFFFFFFFF;
    int* ip = (int*)&ui;
    int si = *ip;  // OK: signed/unsigned correspondence

    std::cout << "Unsigned: " << ui << "\n";
    std::cout << "As signed: " << si << "\n\n";
}

// Example 5: LEGAL - Base class access
class Base {
public:
    virtual ~Base() {}
    int base_val = 100;
};

class Derived : public Base {
public:
    int derived_val = 200;
};

void demonstrate_base_access() {
    std::cout << "--- LEGAL: Base Class Access ---\n";

    Derived d;
    Base* bp = &d;  // Derived to Base pointer
    int val = bp->base_val;  // OK: accessing Derived through Base*

    std::cout << "Accessing Derived through Base*: " << val << "\n\n";
}

// Example 6: LEGAL - Aggregate member access
struct Point {
    int x;
    int y;
};

void demonstrate_aggregate_access() {
    std::cout << "--- LEGAL: Aggregate Member Access ---\n";

    Point p = {10, 20};
    int* xp = &p.x;  // OK: accessing int member through int*
    int x_val = *xp;

    // Also legal: accessing Point through int* to first member
    int* pp = (int*)&p;
    int first = *pp;  // OK: aggregate contains int

    std::cout << "Point.x via member pointer: " << x_val << "\n";
    std::cout << "Point first member via cast: " << first << "\n\n";
}

// Example 7: Union (implementation-defined but widely supported)
union TypePun {
    float f;
    uint32_t u;
};

void demonstrate_union() {
    std::cout << "--- Union Type Punning (impl-defined) ---\n";

    TypePun pun;
    pun.f = 3.14159f;

    std::cout << "Float: " << pun.f << "\n";
    std::cout << "Bits: 0x" << std::hex << pun.u << std::dec << "\n\n";
}

int main() {
    std::cout << "=== Strict Aliasing Rule Demo ===\n\n";

    demonstrate_ub_violation();
    demonstrate_char_access();
    demonstrate_memcpy();
    demonstrate_signed_unsigned();
    demonstrate_base_access();
    demonstrate_aggregate_access();
    demonstrate_union();

    std::cout << "\nKey Takeaway: Use memcpy or char* for safe type punning.\n";
    std::cout << "Casting incompatible pointer types leads to undefined behavior.\n";

    return 0;
}

